#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int u, v, w, c; // c: 0 = A, 1 = B
};

struct DSU {
    vector<int> p, r;
    DSU(int n = 0) { init(n); }
    void init(int n) {
        p.resize(n);
        r.assign(n, 0);
        iota(p.begin(), p.end(), 0);
    }
    int find(int x) {
        return p[x] == x ? x : p[x] = find(p[x]);
    }
    bool unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return false;
        if (r[a] < r[b]) swap(a, b);
        p[b] = a;
        if (r[a] == r[b]) r[a]++;
        return true;
    }
};

static const long long INF = (1LL << 60);

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k;
    while (cin >> n >> m >> k) {
        if (n == 0 && m == 0 && k == 0) break;

        vector<Edge> edges;
        edges.reserve(m);

        for (int i = 0; i < m; ++i) {
            int u, v, w;
            char comp;
            cin >> u >> v >> w >> comp;
            --u; --v;
            int c = (comp == 'A' ? 0 : 1);
            edges.push_back({u, v, w, c});
        }

        long long answer = INF;

        // Lagrangian relaxation:
        // For lambda, modify weight:
        // A-edge => w + lambda
        // B-edge => w
        // Compute MST minimizing modified weight.
        // Let cntA be number of A-edges in that MST.
        // We need exactly k A-edges.
        //
        // Try a range of lambda values and keep solutions with cntA == k.
        // Since constraints are not given here, use integer search over all
        // relevant lambdas derived from costs. Practical and safe with binary search
        // on monotonic cntA.
        //
        // To handle ties and exact k robustly, compute:
        // 1) MST preferring A in ties
        // 2) MST preferring B in ties
        // and binary search lambda.

        auto mst = [&](long long lambda, bool preferA) -> pair<long long,int> {
            vector<int> idx(m);
            iota(idx.begin(), idx.end(), 0);

            auto modw = [&](const Edge& e) -> long long {
                return e.w + (e.c == 0 ? lambda : 0LL);
            };

            sort(idx.begin(), idx.end(), [&](int i, int j) {
                long long wi = modw(edges[i]);
                long long wj = modw(edges[j]);
                if (wi != wj) return wi < wj;
                if (edges[i].c != edges[j].c) {
                    if (preferA) return edges[i].c < edges[j].c; // A first
                    else return edges[i].c > edges[j].c;         // B first
                }
                return i < j;
            });

            DSU dsu(n);
            long long totalMod = 0;
            int cntA = 0, used = 0;

            for (int id : idx) {
                const auto& e = edges[id];
                if (dsu.unite(e.u, e.v)) {
                    totalMod += modw(e);
                    if (e.c == 0) cntA++;
                    used++;
                    if (used == n - 1) break;
                }
            }

            if (used != n - 1) return {INF, -1};
            return {totalMod, cntA};
        };

        // Binary search lambda where number of A-edges changes across k.
        long long lo = -1000000000LL, hi = 1000000000LL;

        for (int it = 0; it < 50; ++it) {
            long long mid = (lo + hi) / 2;
            auto res = mst(mid, true);
            int cntA = res.second;
            if (cntA == -1) break;
            if (cntA >= k) lo = mid;
            else hi = mid;
        }

        // Check around the boundary.
        for (long long lambda = lo - 3; lambda <= hi + 3; ++lambda) {
            for (int pref = 0; pref < 2; ++pref) {
                auto res = mst(lambda, pref == 0);
                if (res.second == k) {
                    long long realCost = res.first - lambda * 1LL * k;
                    answer = min(answer, realCost);
                }
            }
        }

        if (answer == INF) cout << "impossible\n";
        else cout << answer << "\n";
    }

    return 0;
}

