#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    int u, v;
    ll w;
    int a; /* 1 if company A, 0 if company B */
} Edge;

typedef struct {
    int u, v;
    ll w2; /* transformed weight = w + lambda if A, else w */
    int a;
} TEdge;

typedef struct {
    int parent;
    int rank;
} DSU;

static int cmp_edge(const void *p1, const void *p2) {
    const TEdge *x = (const TEdge *)p1;
    const TEdge *y = (const TEdge *)p2;
    if (x->w2 < y->w2) return -1;
    if (x->w2 > y->w2) return 1;
    /* For equal transformed weight, prefer A-edges.
       This makes the number of A-edges in the MST maximal among minimum transformed-cost MSTs,
       which is useful for the parametric search. */
    if (x->a != y->a) return y->a - x->a;
    return 0;
}

static void dsu_init(DSU *dsu, int n) {
    for (int i = 1; i <= n; i++) {
        dsu[i].parent = i;
        dsu[i].rank = 0;
    }
}

static int dsu_find(DSU *dsu, int x) {
    if (dsu[x].parent != x) dsu[x].parent = dsu_find(dsu, dsu[x].parent);
    return dsu[x].parent;
}

static int dsu_union(DSU *dsu, int a, int b) {
    a = dsu_find(dsu, a);
    b = dsu_find(dsu, b);
    if (a == b) return 0;
    if (dsu[a].rank < dsu[b].rank) {
        dsu[a].parent = b;
    } else if (dsu[a].rank > dsu[b].rank) {
        dsu[b].parent = a;
    } else {
        dsu[b].parent = a;
        dsu[a].rank++;
    }
    return 1;
}

/* Builds MST under transformed weights:
   weight' = w + lambda for A edges, weight' = w for B edges.
   Returns:
     connected = 1 if spanning tree exists, else 0
     cntA = number of A-edges in chosen MST
     realCost = sum of original weights
*/
static void mst_with_lambda(int n, int m, Edge *edges, ll lambda,
                            int *connected, int *cntA, ll *realCost) {
    TEdge *arr = (TEdge *)malloc(sizeof(TEdge) * m);
    DSU *dsu = (DSU *)malloc(sizeof(DSU) * (n + 1));

    for (int i = 0; i < m; i++) {
        arr[i].u = edges[i].u;
        arr[i].v = edges[i].v;
        arr[i].a = edges[i].a;
        arr[i].w2 = edges[i].w + (edges[i].a ? lambda : 0);
    }

    qsort(arr, m, sizeof(TEdge), cmp_edge);
    dsu_init(dsu, n);

    int used = 0, ca = 0;
    ll rc = 0;

    for (int i = 0; i < m && used < n - 1; i++) {
        if (dsu_union(dsu, arr[i].u, arr[i].v)) {
            used++;
            rc += arr[i].w2 - (arr[i].a ? lambda : 0); /* original weight */
            if (arr[i].a) ca++;
        }
    }

    *connected = (used == n - 1);
    *cntA = ca;
    *realCost = rc;

    free(arr);
    free(dsu);
}

int main(void) {
    int n, m, k;

    while (scanf("%d %d %d", &n, &m, &k) == 3) {
        Edge *edges = (Edge *)malloc(sizeof(Edge) * m);

        for (int i = 0; i < m; i++) {
            char c[8];
            scanf("%d %d %lld %s", &edges[i].u, &edges[i].v, &edges[i].w, c);
            edges[i].a = (c[0] == 'A');
        }

        /* First, check if any spanning tree exists at all. */
        int connected, cntA;
        ll realCost;
        mst_with_lambda(n, m, edges, 0, &connected, &cntA, &realCost);
        if (!connected) {
            printf("Impossible\n");
            free(edges);
            continue;
        }

        /* Parametric search on lambda.
           As lambda increases, A-edges become less attractive, so cntA is non-increasing.
           We seek lambda such that an MST can have exactly k A-edges.
           With our tie-breaking, mst_with_lambda returns the maximum cntA among optimal transformed MSTs.
        */
        ll lo = -1000000000000LL, hi = 1000000000000LL;

        while (lo < hi) {
            ll mid = lo + (hi - lo) / 2;
            mst_with_lambda(n, m, edges, mid, &connected, &cntA, &realCost);
            if (!connected) {
                /* Should not happen after initial connectivity check, but keep safe. */
                break;
            }
            if (cntA >= k) lo = mid + 1;
            else hi = mid;
        }

        /* Candidate lambdas around boundary */
        ll ans = -1;
        for (ll lam = lo - 3; lam <= lo + 3; lam++) {
            mst_with_lambda(n, m, edges, lam, &connected, &cntA, &realCost);
            if (!connected) continue;
            if (cntA == k) {
                if (ans == -1 || realCost < ans) ans = realCost;
            }
        }

        if (ans == -1) {
            /* Also try a wider discrete neighborhood just in case of plateau effects. */
            for (ll lam = lo - 50; lam <= lo + 50; lam++) {
                mst_with_lambda(n, m, edges, lam, &connected, &cntA, &realCost);
                if (!connected) continue;
                if (cntA == k) {
                    if (ans == -1 || realCost < ans) ans = realCost;
                }
            }
        }

        if (ans == -1) printf("Impossible\n");
        else printf("%lld\n", ans);

        free(edges);
    }

    return 0;
}

