public class Main {
    static int[] parent, rank;

    static int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    static boolean union(int x, int y) {
        x = find(x); y = find(y);
        if (x == y) return false;
        if (rank[x] < rank[y]) { int t = x; x = y; y = t; }
        parent[y] = x;
        if (rank[x] == rank[y]) rank[x]++;
        return true;
    }

    // Returns [total_cost, count_of_A_edges] with penalty p added to A edges
    static long[] mst(int n, int[][] edges, double p) {
        // edges: [u, v, cost, type(0=A,1=B)]
        int m = edges.length;
        Integer[] idx = new Integer[m];
        for (int i = 0; i < m; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> Double.compare(
            edges[a][2] + (edges[a][3] == 0 ? p : 0),
            edges[b][2] + (edges[b][3] == 0 ? p : 0)
        ));
        parent = new int[n]; rank = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;
        long cost = 0; int countA = 0, edgeCount = 0;
        for (int i : idx) {
            if (union(edges[i][0], edges[i][1])) {
                cost += edges[i][2];
                if (edges[i][3] == 0) countA++;
                edgeCount++;
                if (edgeCount == n - 1) break;
            }
        }
        if (edgeCount < n - 1) return null;
        return new long[]{cost, countA};
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int n = sc.nextInt();
            if (n == 0) break;
            int m = sc.nextInt();
            int k = sc.nextInt();
            int[][] edges = new int[m][4];
            for (int i = 0; i < m; i++) {
                edges[i][0] = sc.nextInt() - 1;
                edges[i][1] = sc.nextInt() - 1;
                edges[i][2] = sc.nextInt();
                String c = sc.next();
                edges[i][3] = c.equals("A") ? 0 : 1;
            }

            // Binary search on penalty p
            double lo = -100001, hi = 100001;
            for (int iter = 0; iter < 100; iter++) {
                double mid = (lo + hi) / 2;
                long[] res = mst(n, edges, mid);
                if (res == null) { lo = mid; continue; }
                if (res[1] > k) lo = mid;
                else hi = mid;
            }

            long[] res = mst(n, edges, hi);
            if (res == null || res[1] != k) {
                // try lo
                res = mst(n, edges, lo);
            }
            if (res == null || res[1] != k) {
                System.out.println("impossible");
            } else {
                // actual cost = mst_cost(with penalty) - k * penalty
                long[] res2 = mst(n, edges, hi);
                long actualCost = res2[0] - (long)(k * hi + 0.5);
                // Recompute properly
                System.out.println(actualCost);
            }
        }
    }
}

