import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return Integer.MIN_VALUE;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        String next() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            StringBuilder sb = new StringBuilder();
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }

    static class Edge {
        int u, v, cost, company; // 0 = A, 1 = B
        Edge(int u, int v, int cost, int company) {
            this.u = u;
            this.v = v;
            this.cost = cost;
            this.company = company;
        }
    }

    static class DSU {
        int[] p, r;
        DSU(int n) {
            p = new int[n];
            r = new int[n];
            for (int i = 0; i < n; i++) p[i] = i;
        }
        int find(int x) {
            while (p[x] != x) {
                p[x] = p[p[x]];
                x = p[x];
            }
            return x;
        }
        boolean union(int a, int b) {
            int ra = find(a), rb = find(b);
            if (ra == rb) return false;
            if (r[ra] < r[rb]) p[ra] = rb;
            else if (r[ra] > r[rb]) p[rb] = ra;
            else {
                p[rb] = ra;
                r[ra]++;
            }
            return true;
        }
    }

    static int n, m, k;
    static List<Edge> edges;

    static long mstWithLambda(int lambda, int[] countAHolder) {
        List<Edge> sorted = new ArrayList<>(edges);
        sorted.sort((e1, e2) -> {
            long w1 = (long)e1.cost + (e1.company == 0 ? lambda : 0);
            long w2 = (long)e2.cost + (e2.company == 0 ? lambda : 0);
            if (w1 != w2) return Long.compare(w1, w2);
            // Prefer A on ties when lambda is same to make count monotonic in a consistent way
            return Integer.compare(e2.company, e1.company);
        });

        DSU dsu = new DSU(n);
        long modifiedCost = 0;
        int used = 0;
        int countA = 0;

        for (Edge e : sorted) {
            if (dsu.union(e.u, e.v)) {
                modifiedCost += e.cost + (e.company == 0 ? lambda : 0L);
                used++;
                if (e.company == 0) countA++;
                if (used == n - 1) break;
            }
        }

        if (used != n - 1) {
            countAHolder[0] = -1;
            return Long.MAX_VALUE / 4;
        }
        countAHolder[0] = countA;
        return modifiedCost;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
