                edges.add(new Edge(u - 1, v - 1, c, company));
            }

            if (k < 0 || k > n - 1) {
                out.append("impossible\n");
                continue;
            }

            // Binary search on lambda.
            // As lambda increases, A-edges become less attractive, so countA is non-increasing.
            int low = -1_000_000;
            int high = 1_000_000;

            // Expand range if needed (safe enough for typical constraints)
            int[] holder = new int[1];
            mstWithLambda(low, holder);
            int cntLow = holder[0];
            mstWithLambda(high, holder);
            int cntHigh = holder[0];

            // If graph disconnected for all, impossible
            if (cntLow == -1 || cntHigh == -1) {
                // Need one more check: maybe disconnected due to chosen lambda tie behavior? No, connectivity independent.
                out.append("impossible\n");
                continue;
            }

            // Need some lambda where countA >= k and some where countA <= k
            if (!(cntLow >= k && cntHigh <= k)) {
                out.append("impossible\n");
                continue;
            }

            while (low < high) {
                int mid = low + (high - low) / 2;
                long val = mstWithLambda(mid, holder);
                int cnt = holder[0];
                if (cnt == -1) {
                    low = mid + 1;
                } else if (cnt <= k) {
                    high = mid;
                } else {
                    low = mid + 1;
                }
            }

            int lambda = low;
            long modified = mstWithLambda(lambda, holder);
            int cnt = holder[0];

            if (cnt == -1 || cnt != k) {
                // Due to discrete jumps, exact k may be unattainable
                out.append("impossible\n");
            } else {
                long originalCost = modified - (long) lambda * k;
